INSERT INTO `pois` (`id`, `name`, `category`, `lng`, `lat`, `adcode`, `address`, `summary`, `cover_url`, `hint_text`, `difficulty`, `source`, `used_count`, `verify_status`, `shape_type`, `radius_km`, `area_review`) VALUES
('6201', '天津世纪钟广场', '景点', '117.202', '39.122', '120101', '天津市和平区劝业场街道回回牛肉饼(河北路店)河南里', '世纪钟是天津的标志性雕塑，位于海河之畔，钟体高40米，金属质感浓厚，是天津建城600周年的纪念。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6201.jpg', '海河畔40米金属雕塑', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6202', '天津水上公园', '公园', '117.176', '39.084', '120104', '天津市南开区体育中心街道翠湖温泉花园翠泉别墅西区', '天津水上公园是市区最大的综合性公园，以水面为主，拥有东湖、西湖、南湖三大湖泊，景色秀丽。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6202.jpg', '天津最大的水上主题公园', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6203', '天津广播电视塔', 'famous_buildings', '117.173', '39.075', '120104', '天津市南开区体育中心街道天津奥林匹克中心', '天塔高415米，是天津的标志性建筑，世界第六高塔，可俯瞰天津全城。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6203.jpg', '415米高塔，天津地标', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6204', '大悲禅院', '寺庙', '117.174', '39.161', '120106', '天津市红桥区西沽街道同义庄大街', '大悲禅院是天津最大的佛教寺院，始建于清代，供奉观世音菩萨，是天津佛教协会所在地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6204.jpg', '天津最大佛教寺院', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6205', '南市食品街', '景点', '117.202', '39.129', '120101', '天津市和平区小白楼街道兴安路天津·金街', '南市食品街是天津特色美食聚集地，汇集了天津麻花、狗不理包子、煎饼果子等传统小吃。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6205.jpg', '天津传统小吃聚集地', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6206', '意式风情街', '景点', '117.203', '39.137', '120105', '天津市河北区光复道街道天津行车公寓天津·海河意式风情区', '天津意式风情区是中国唯一的意式风情区，拥有200余栋地中海风格建筑，充满异国情调。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6206.jpg', '中国唯一意式风情区', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6207', '静园', 'historic_city', '117.197', '39.127', '120101', '天津市和平区劝业场街道新华路48号天津沈阳道古物市场', '静园是末代皇帝溥仪在天津的故居，建于1921年，为西班牙与日式结合的建筑风格。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6207.jpg', '溥仪在天津的故居', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6208', '西开教堂', '寺庙', '117.207', '39.124', '120101', '天津市和平区小白楼街道光学新里', '西开教堂是天津最大的天主教堂，建于1916年，为典型的哥特式建筑，是天津天主教总堂。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6208.jpg', '天津最大天主教堂', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6209', '庆王府', 'historic_city', '117.197', '39.122', '120101', '天津市和平区劝业场街道庆泰里in base时尚基地(滨江道店)', '庆王府是清末庆亲王载振的府邸，位于重庆道55号，为天津重点历史风貌建筑。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6209.jpg', '清末庆亲王在天津的府邸', '4', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6210', '塘沽海河外滩公园', '公园', '117.715', '39.025', '120116', '天津市滨海新区泰达街道宏达街南开大学(泰达校区)', '塘沽海河外滩公园位于滨海新区，是海河入海前的最后一段景观带，可远眺海河交汇。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6210.jpg', '海河入海口景观公园', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6211', '国父纪念馆', 'famous_buildings', '121.558', '25.041', '710100', '台湾 台北市 信义区 国父纪念馆', '国父纪念馆为纪念孙中山先生而建，由王大闳设计，1972年落成，是台北重要地标和文化活动中心。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6211.jpg', '台北纪念孙中山的地标建筑', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6212', '行天宫', '寺庙', '121.534', '25.064', '710100', '台湾 台北市 中山区 行天宫', '行天宫是台北著名的关帝庙，供奉关圣帝君，香火鼎盛，是台北市民信仰中心之一。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6212.jpg', '台北知名关帝庙', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6213', '士林官邸', '景点', '121.53', '25.095', '710100', '台湾 台北市 士林区 士林官邸', '士林官邸是蒋介石在台北的住所，现为生态园林与玫瑰园，是台北著名的历史景点。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6213.jpg', '蒋介石台北住所', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6214', '总统府', 'famous_buildings', '121.513', '25.04', '710100', '台湾 台北市 中正区 总统府', '总统府建于1919年，为文艺复兴风格建筑，是台北最具代表性的历史建筑之一。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6214.jpg', '台北文艺复兴风格历史建筑', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6215', '阳明山国家公园', '公园', '121.548', '25.156', '710100', '台湾 台北市 北投区 阳明山国家公园', '阳明山国家公园以火山地形、温泉、樱花闻名，是台北最近的国家公园，四季景色各异。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6215.jpg', '台北火山温泉国家公园', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6216', '台北车站', 'train_stations', '121.517', '25.048', '710100', '台湾 台北市 中正区 台北车站', '台北车站是台湾最大的铁路枢纽，汇集台铁、高铁、捷运三铁共构，是台北交通中心。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6216.jpg', '台湾最大铁路枢纽', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6217', '饶河街观光夜市', '景点', '121.578', '25.051', '710100', '台湾 台北市 松山区 饶河街夜市', '饶河街夜市是台北最古老的夜市之一，全长600米，汇集各种台湾小吃，是体验台北夜生活的好去处。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6217.jpg', '台北松山区知名夜市', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6218', '西门町', '景点', '121.506', '25.042', '710100', '台湾 台北市 万华区 西门町', '西门町是台北年轻人最爱的商圈，有红楼、电影街、特色小店，是台北流行文化的发源地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6218.jpg', '台北年轻人的流行商圈', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6219', '九份老街', '景点', '121.846', '25.109', '710100', '台湾 新北市 瑞芳区 九份老街', '九份是因金矿而兴起的山城，因电影《悲情城市》和《千与千寻》闻名，红灯笼石阶是标志景观。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6219.jpg', '宫崎骏灵感来源的金矿山城', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6220', '黄金博物馆', 'museum_l1', '121.856', '25.108', '710100', '台湾 新北市 瑞芳区 黄金博物馆', '黄金博物馆位于金瓜石，展示了台湾金矿开采历史，游客可体验淘金，还可参观本山五坑坑道。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6220.jpg', '金瓜石的黄金开采博物馆', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6221', '阿里山森林游乐区', '公园', '120.815', '23.518', '710600', '台湾 嘉义县 阿里山乡 阿里山森林游乐区', '阿里山以五奇著称：日出、云海、晚霞、森林与高山铁路，是台湾最知名的自然风景区之一。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6221.jpg', '日出云海森林铁路五奇', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6222', '清境农场', '景点', '121.159', '24.049', '710800', '台湾 南投县 仁爱乡 清境农场', '清境农场海拔1748米，以高山草原、绵羊秀和雾社樱花闻名，有台湾小瑞士之称。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6222.jpg', '台湾小瑞士高山牧场', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6223', '中台禅寺', '寺庙', '120.944', '24.009', '710800', '台湾 南投县 埔里镇 中台禅寺', '中台禅寺是台湾四大佛教名山之一，建筑雄伟融合中西风格，高37层，是埔里地标。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6223.jpg', '台湾四大佛教名山之一', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6224', '垦丁国家公园', '公园', '120.78', '21.948', '711400', '台湾 屏东县 恒春镇 垦丁国家公园', '垦丁国家公园位于台湾最南端，三面环海，是台湾唯一的热带国家公园，以白沙湾和珊瑚礁闻名。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6224.jpg', '台湾最南端热带国家公园', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6225', '鹅銮鼻灯塔', '景点', '120.853', '21.902', '711400', '台湾 屏东县 恒春镇 鹅銮鼻灯塔', '鹅銮鼻灯塔位于台湾最南端，建于1883年，是东亚最亮的灯塔，有东亚之光的美誉。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6225.jpg', '台湾最南端灯塔', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6226', '赤崁楼', 'historic_city', '120.202', '22.997', '711100', '台湾 台南市 中区 赤崁楼', '赤崁楼是台南最著名的历史古迹，建于1653年，原为荷兰人所建普罗民遮城，是台湾一级古迹。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6226.jpg', '台南荷兰时期历史古迹', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6227', '安平古堡', 'historic_city', '120.161', '23.002', '711100', '台湾 台南市 安平区 安平古堡', '安平古堡是台湾最古老的城堡，建于1624年，原为荷兰东印度公司所建，是台湾历史起点。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6227.jpg', '台湾最古老城堡', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6228', '台南孔庙', '寺庙', '120.204', '22.991', '711100', '台湾 台南市 中区 台南孔庙', '台南孔庙建于1665年，是台湾最早的孔庙，被称为全台首学，是台湾文化的发源地之一。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6228.jpg', '台湾最早的孔庙', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6229', '佛光山佛陀纪念馆', '寺庙', '120.445', '22.756', '711300', '台湾 高雄市 大树区 佛光山佛陀纪念馆', '佛光山佛陀纪念馆占地100公顷，2011年开馆，供奉佛牙舍利，是南台湾最大佛教圣地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6229.jpg', '高雄供奉佛牙舍利圣地', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6230', '六合观光夜市', '景点', '120.302', '22.633', '711300', '台湾 高雄市 前金区 六合夜市', '六合夜市是高雄最具代表性的夜市，全长350米，以各种海鲜小吃和异国美食闻名。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6230.jpg', '高雄最具代表性夜市', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6231', '龙虎塔', '景点', '120.292', '22.68', '711300', '台湾 高雄市 左营区 龙虎塔', '龙虎塔位于莲池潭畔，建于1976年，塔高7层，龙虎双塔并立，是高雄最具特色的建筑。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6231.jpg', '高雄莲池潭畔双塔', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6232', '莲池潭', 'lake_famous', '120.297', '22.685', '711300', '台湾 高雄市 左营区 莲池潭', '莲池潭是高雄左营著名的湖泊风景区，潭面有春秋阁、龙虎塔、孔庙等景观，是高雄知名景点。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6232.jpg', '高雄左营著名湖泊景区', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6233', '台中歌剧院', 'famous_buildings', '120.641', '24.163', '710900', '台湾 台中市 西屯区 台中国家歌剧院', '台中国家歌剧院由日本建筑师伊东丰雄设计，以无墙体曲面建筑闻名，是台中文化地标。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6233.jpg', '伊东丰雄设计的曲面建筑', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6234', '彩虹眷村', '景点', '120.61', '24.134', '710900', '台湾 台中市 南屯区 彩虹眷村', '彩虹眷村由老兵黄永阜用彩绘改造眷村墙面，色彩缤纷的涂鸦使老眷村重生为艺术村。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6234.jpg', '老兵彩绘重生的眷村', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6235', '鹿港老街', 'historic_city', '120.433', '24.05', '710700', '台湾 彰化县 鹿港镇 鹿港老街', '鹿港是台湾著名古镇，曾为台湾第二大城，老街保留大量清代闽南建筑，是台湾文化重镇。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6235.jpg', '台湾清代第二大城古镇', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6236', '太鲁阁国家公园', '公园', '121.628', '24.158', '711200', '台湾 花莲县 秀林乡 太鲁阁国家公园', '太鲁阁国家公园以大理岩峡谷闻名，太鲁阁族原住民世居于此，是台湾最壮丽的自然景观之一。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6236.jpg', '大理岩峡谷原住民圣地', '2', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6237', '高美湿地', '景点', '120.56', '24.31', '710900', '台湾 台中市 清水区 高美湿地', '高美湿地位于台中清水区，以丰富的湿地生态和壮观的日落美景闻名，是台中知名赏景地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6237.jpg', '台中日落湿地', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6238', '七星潭', '景点', '121.63', '24.03', '711200', '台湾 花莲市 七星潭', '七星潭是花莲最著名的海滨景点，为月牙形砾石海湾，可远眺清水断崖，是花莲必游之地。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6238.jpg', '花莲月牙形砾石海湾', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6239', '十分瀑布', '景点', '121.776', '25.045', '710100', '台湾 新北市 平溪区 十分瀑布', '十分瀑布是台湾最宽的帘幕式瀑布，宽40米高15米，有台湾尼加拉瀑布之美誉。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6239.jpg', '台湾最宽帘幕式瀑布', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
('6240', '十分老街', '景点', '121.773', '25.048', '710100', '台湾 新北市 平溪区 十分老街', '十分老街以天灯文化闻名，游客在此放天灯祈福，火车从老街中穿过是独特景观。', 'https://map-find.oss-cn-beijing.aliyuncs.com/covers/6240.jpg', '天灯文化发源地老街', '3', 'manual', '0', 'approved', 'point', '0.0', '1'),
